<script setup>
import { computed, inject, onMounted, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import StudioFrame from '../components/StudioFrame.vue';
import { get, post, put, patch, remove, failure } from '../lib';
const props=defineProps({user:{type:Object,required:true}}); const emit=defineEmits(['logout']);
const {toast,reloadSite}=inject('session'); const router=useRouter(); const route=useRoute();
const section=computed(()=>route.params.section||'overview');
const labels={overview:'Good to see you.',pages:'Your pages',media:'Media library',navigation:'Navigation',settings:'Site settings',team:'Your team'};
const subtitle={overview:'Here’s what’s happening in your world.',pages:'Everything you publish starts here.',media:'All your visual assets, in one place.',navigation:'Help people find their way around.',settings:'Make FastFind your own.',team:'Give the right people the right access.'};
const data=ref({}); const loading=ref(true); const error=ref(''); const query=ref(''); const newName=ref(''); const busy=ref(false);
const brand=ref({name:'FastFind',tagline:''}); const nav=ref([]); const team=ref([]);
const newUser=ref({name:'',email:'',password:'',role:'editor'});
const uploadFile=ref(null); const alt=ref('');
const canEdit=computed(()=>['owner','admin','editor'].includes(props.user.role));
const canManage=computed(()=>['owner','admin'].includes(props.user.role));
const filteredPages=computed(()=> (data.value.data||[]).filter(x=>(x.title+' '+x.slug).toLowerCase().includes(query.value.toLowerCase())));
async function load() { loading.value=true;error.value=''; try { if(section.value==='overview')data.value=await get('/studio/dashboard'); if(section.value==='pages')data.value=await get('/studio/pages'); if(section.value==='media')data.value=await get('/studio/media'); if(section.value==='navigation')nav.value=(await get('/studio/navigation')).navigation; if(section.value==='settings')brand.value=(await get('/studio/settings')).brand; if(section.value==='team')team.value=(await get('/studio/users')).users; } catch(e){error.value=failure(e);} finally{loading.value=false;} }
watch(section,load); onMounted(load);
async function createPage(){if(!newName.value.trim()||busy.value)return; busy.value=true;try{const p=(await post('/studio/pages',{title:newName.value})).page;router.push('/studio/pages/'+p.id);}catch(e){toast(failure(e));}finally{busy.value=false;}}
async function deletePage(p){if(!confirm(`Delete “${p.title}” and all its revisions permanently?`))return;try{await remove('/studio/pages/'+p.id,{version:p.version});toast('Page deleted.');await load();}catch(e){toast(failure(e));}}
async function upload(){if(!uploadFile.value||busy.value)return; busy.value=true;const f=new FormData();f.append('file',uploadFile.value);f.append('alt',alt.value);try{await post('/studio/media',f);uploadFile.value=null;alt.value='';toast('File uploaded.');await load();}catch(e){toast(failure(e));}finally{busy.value=false;}}
async function deleteAsset(a){if(!confirm('Remove this file? This may break links that use it.'))return;try{await remove('/studio/media/'+a.id);await load();toast('Asset deleted.');}catch(e){toast(failure(e));}}
async function saveNavigation(){try{nav.value=(await put('/studio/navigation',{items:nav.value.map(x=>({label:x.label,url:x.url,visible:!!x.visible}))})).navigation;toast('Navigation updated.');await reloadSite();}catch(e){toast(failure(e));}}
async function saveSettings(){try{brand.value=(await put('/studio/settings',brand.value)).brand;toast('Brand updated.');await reloadSite();}catch(e){toast(failure(e));}}
async function createUser(){try{await post('/studio/users',newUser.value);toast('Team member added.');newUser.value={name:'',email:'',password:'',role:'editor'};await load();}catch(e){toast(failure(e));}}
async function updateUser(member){try{await patch('/studio/users/'+member.id,{role:member.role,is_active:member.is_active});toast('Permissions saved.');}catch(e){toast(failure(e));await load();}}
function moveNav(i, delta){const j=i+delta;if(j<0||j>=nav.value.length)return;[nav.value[i],nav.value[j]]=[nav.value[j],nav.value[i]];}
async function copyUrl(url){ try { if (!navigator.clipboard) throw new Error('Clipboard is unavailable in this browser.'); await navigator.clipboard.writeText(new URL(url, window.location.origin).href); toast('Image URL copied.'); } catch(e) { toast(e.message || 'Could not copy the image URL.'); } }
function createShortcut(){ if(section.value==='pages') document.getElementById('pageName')?.focus(); else router.push('/studio/pages'); }
function formatDate(value){return value?new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'—';}
</script>
<template>
<StudioFrame :user="user" :page-title="labels[section]||'Studio'" :subtitle="subtitle[section]||''" @logout="emit('logout')">
  <template #toolbar><button v-if="section==='overview'||section==='pages'" class="btn primary" :disabled="!canEdit" @click="createShortcut()">+ {{ section==='pages'?'New page':'Explore pages' }}</button></template>
  <div v-if="loading" class="admin-loading"><span>✳</span> Gathering your content…</div>
  <div v-else-if="error" class="alert error">{{ error }} <button @click="load" class="text-link">Try again</button></div>
  <template v-else-if="section==='overview'">
    <div class="welcome-strip"><span class="eyebrow">YOUR CREATIVE SPACE</span><h2>Big ideas start small.<br><em>Make something today.</em></h2><p>Everything you need to turn a thought into something worth sharing.</p><RouterLink class="btn light" to="/studio/pages">Create something new ↗</RouterLink><span class="strip-art">✳</span></div>
    <div class="kpi-grid"><div v-for="(value,key) in {pages:data.pages,published:data.published,drafts:data.drafts,media:data.media}" :key="key" class="kpi-card"><span class="eyebrow">{{ key.toUpperCase() }}</span><strong>{{ value ?? 0 }}</strong><small>{{ {pages:'Total content',published:'Live on your site',drafts:'Works in progress',media:'Uploaded visuals'}[key] }} <span>↗</span></small></div></div>
    <div class="dashboard-columns"><section class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">PICK UP WHERE YOU LEFT OFF</span><h2>Recent pages</h2></div><RouterLink class="text-link" to="/studio/pages">View all →</RouterLink></div><RouterLink v-for="p in data.recent" :key="p.id" :to="'/studio/pages/'+p.id" class="dashboard-page"><span class="dash-page-icon">▤</span><div><strong>{{p.title}}</strong><small>Edited {{formatDate(p.updated_at)}}</small></div><span :class="['state-pill',p.status]">{{p.status}}</span><b>↗</b></RouterLink><div v-if="!data.recent?.length" class="pad-note">Your recent pages will appear here.</div></section><section class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">WORKSPACE PULSE</span><h2>Recent activity</h2></div></div><div v-for="(ev,i) in data.events" :key="i" class="activity-row"><span class="activity-dot">✳</span><div><strong>{{ev.action.replace('.',' · ')}}</strong><small>{{formatDate(ev.created_at)}}</small></div></div><p v-if="!data.events?.length" class="pad-note">Your activity feed is ready for its first chapter.</p></section></div>
  </template>
  <template v-else-if="section==='pages'"><div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">CONTENT COLLECTION</span><h2>Every story has a home.</h2></div><span class="muted">{{data.total || 0}} pages</span></div><div class="page-tools"><div class="search-input"><span>⌕</span><input v-model="query" aria-label="Find pages" placeholder="Find a page by title or slug…" /></div><form v-if="canEdit" class="quick-add" @submit.prevent="createPage"><input id="pageName" v-model.trim="newName" aria-label="New page title" placeholder="New page title" maxlength="180" required/><button class="btn primary" :disabled="busy">Create page ↗</button></form></div><div class="table-scroll"><table class="data-table"><thead><tr><th>PAGE</th><th>STATUS</th><th>LAST UPDATED</th><th></th></tr></thead><tbody><tr v-for="p in filteredPages" :key="p.id"><td><RouterLink class="table-title" :to="'/studio/pages/'+p.id">{{p.title}}</RouterLink><small>/p/{{p.slug}}</small></td><td><span :class="['state-pill',p.status]">{{p.status}}</span></td><td>{{formatDate(p.updated_at)}}</td><td class="cell-actions"><RouterLink class="icon-button" :to="'/studio/pages/'+p.id" title="Open editor">↗</RouterLink><button v-if="canEdit" class="icon-button danger-ink" title="Delete" @click="deletePage(p)">×</button></td></tr></tbody></table><div v-if="!filteredPages.length" class="empty-admin">No pages match your search. Create one to get started.</div></div><button v-if="data.next_page_url" class="btn outline" @click="get('/studio/pages?page='+(data.current_page+1)).then(x=>data=x)">Next page →</button></div></template>
  <template v-else-if="section==='media'"><div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">VISUAL LIBRARY</span><h2>Everything in its place.</h2></div><span class="muted">PNG · JPEG · WEBP · GIF / 5 MB max</span></div><form v-if="canEdit" class="upload-panel" @submit.prevent="upload"><div><strong>Add something visual</strong><p>Give images descriptive alt text for accessibility.</p></div><label class="file-control"><input type="file" accept="image/png,image/jpeg,image/webp,image/gif" @change="uploadFile=$event.target.files[0]" required/><span>{{uploadFile?.name||'Choose image'}}</span></label><input v-model="alt" aria-label="Image description" placeholder="Image description (alt text)" maxlength="255"/><button :disabled="busy" class="btn primary">Upload ↗</button></form><div class="media-grid"><div v-for="asset in data.media" :key="asset.id" class="media-tile"><img :src="asset.url" :alt="asset.alt"/><div class="media-caption"><strong :title="asset.filename">{{asset.filename}}</strong><button class="icon-button" title="Copy image URL" @click="copyUrl(asset.url)">⧉</button><button v-if="canManage" class="icon-button danger-ink" @click="deleteAsset(asset)">×</button></div></div></div><div v-if="!data.media?.length" class="empty-admin">No images uploaded yet. Bring your story to life with visuals.</div></div></template>
  <template v-else-if="section==='navigation'"><div class="admin-panel form-card"><span class="eyebrow">SITE NAVIGATION</span><h2>Help readers find their way.</h2><p>These links appear across your public website. Use root-relative paths such as <code>/p/about</code>.</p><div class="navigation-editor"><div v-for="(n,i) in nav" :key="n.id || i" class="nav-edit-row"><span class="drag-handle">⠿</span><input v-model="n.label" aria-label="Navigation label" placeholder="Label"/><input v-model="n.url" aria-label="Navigation URL" placeholder="/p/my-page"/><label class="compact-check"><input type="checkbox" v-model="n.visible"/>Show</label><div class="reorder-small"><button @click="moveNav(i,-1)">↑</button><button @click="moveNav(i,1)">↓</button></div><button class="icon-button danger-ink" @click="nav.splice(i,1)">×</button></div></div><div class="form-actions"><button class="btn outline" :disabled="nav.length>=20" @click="nav.push({label:'New link',url:'/',visible:true})">+ Add link</button><button class="btn primary" @click="saveNavigation">Save navigation ↗</button></div></div></template>
  <template v-else-if="section==='settings'"><div class="admin-panel form-card"><span class="eyebrow">BRAND & IDENTITY</span><h2>Make it unmistakably yours.</h2><p>Your site name and tagline appear across your public experience.</p><form class="settings-form" @submit.prevent="saveSettings"><label>Site name<input v-model="brand.name" required maxlength="80"/></label><label>Tagline<input v-model="brand.tagline" maxlength="180"/></label><div class="brand-preview"><span class="eyebrow">A LITTLE PREVIEW</span><div class="brand"><span class="brand-mark">✳</span><span>{{brand.name}}<span class="brand-period">.</span></span></div><p>{{brand.tagline}}</p></div><button class="btn primary">Save changes ↗</button></form></div></template>
  <template v-else-if="section==='team'"><div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">PEOPLE & PERMISSIONS</span><h2>Better together.</h2></div><span class="muted">{{team.length}} members</span></div><form class="team-create" @submit.prevent="createUser"><input v-model.trim="newUser.name" required maxlength="120" aria-label="Full name" placeholder="Full name"/><input v-model.trim="newUser.email" type="email" required aria-label="Email address" placeholder="Email address"/><input v-model="newUser.password" type="password" minlength="12" required aria-label="Temporary password" placeholder="Temporary password (12+ chars)"/><select aria-label="New user role" v-model="newUser.role"><option value="editor">Editor</option><option value="viewer">Viewer</option><option value="admin">Admin</option><option value="owner">Owner</option></select><button class="btn primary">Add member ↗</button></form><div v-for="person in team" :key="person.id" class="team-row"><div class="avatar dark-avatar">{{person.name[0]}}</div><div class="team-details"><strong>{{person.name}} <small v-if="person.id===user.id">(You)</small></strong><small>{{person.email}}</small></div><select :aria-label="person.name + ' role'" v-model="person.role"><option v-for="role in ['owner','admin','editor','viewer']" :key="role" :value="role">{{role}}</option></select><label class="compact-check"><input type="checkbox" v-model="person.is_active"/>Active</label><button class="btn outline small" @click="updateUser(person)">Save</button></div></div></template>
  <div v-else class="empty-admin">Workspace page not found. Use the navigation to choose an available page.</div>
</StudioFrame>
</template>
